  7	use release_harness::{callisto, git, DECISION_PATH};
  8	
  9	/// Cargo `foo` 1.0.0 in `crates/foo`, released as `foo@1.0.0`.
 10	fn released_cargo_foo() -> tempfile::TempDir {
 11	    let dir = tempfile::tempdir().unwrap();
 12	    let root = dir.path();
 13	    callisto_fixtures::git::init_repo(root);
 14	    git(root, &["remote", "add", "origin", "https://github.com/example/foo.git"]);
 15	    fs::write(
 16	        root.join("Cargo.toml"),
 17	        "[workspace]\nmembers = [\"crates/foo\"]\nresolver = \"2\"\n",
 18	    )
 19	    .unwrap();
 20	    fs::create_dir_all(root.join("crates/foo/src")).unwrap();
 21	    fs::write(
 22	        root.join("crates/foo/Cargo.toml"),
 23	        "[package]\nname = \"foo\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
 24	    )
 25	    .unwrap();
 26	    fs::write(root.join("crates/foo/src/lib.rs"), "\n").unwrap();
