280	/// Resolves native baselines, attributing historical bare keys at the commit that added `pre.json`.
281	pub(crate) fn assign_promoted_pre_keys<D: DependencyResolver>(
282	    git: &GitAccess<'_>,
283	    graph: &D,
284	    identity: &IdentityIndex,
285	    pre_json: &std::path::Path,
286	    mut state: callisto_model::format::PreState,
287	    raw_versions: &indexmap::IndexMap<String, String>,
288	) -> Result<callisto_model::format::PreState, GraphError> {
289	    let keys: Vec<String> = state.initial_versions.keys().cloned().collect();
290	    let mut owners = BTreeMap::new();
291	    for key in &keys {
292	        if let Some(owner) = graph.packages().find(|p| pre_json_key(&p.id) == *key) {
293	            owners.insert(key.clone(), owner);
294	            continue;
295	        }
296	        let same: Vec<&callisto_model::Package> = graph
297	            .packages()
298	            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
299	            .collect();
300	        let owner = if same.is_empty() {
301	            match identity.resolve(key) {
302	                Ok(id) => graph.packages().find(|p| p.id == id),
303	                Err(GraphError::UnknownPackage { .. }) => None,
304	                Err(GraphError::AmbiguousName { candidates, .. }) => {
305	                    return Err(GraphError::AmbiguousPreJsonKey {
306	                        key: key.clone(),
307	                        candidates,
308	                    });
309	                }
310	                Err(error) => return Err(error),
311	            }
312	        } else {
313	            let owner = match git.commit_adding(pre_json).map_err(GraphError::Vcs)? {
314	                Some(added) => sole_owner_at(git, &added, &same)?,
315	                None => None,
316	            };
317	            Some(owner.ok_or_else(|| GraphError::AmbiguousPreJsonKey {
318	                key: key.clone(),
319	                candidates: same.iter().map(|p| p.id.clone()).collect(),
320	            })?)
321	        };
322	        if let Some(owner) = owner {
323	            owners.insert(key.clone(), owner);
324	        }
325	    }
326	    state
327	        .resolve_initial_versions_from_raw(raw_versions, |key| {
328	            owners
329	                .get(key)
330	                .and_then(|owner| owner.canonical_manifests().next().map(|manifest| manifest.ecosystem()))
331	        })
332	        .map_err(GraphError::PreJson)?;
333	    for key in keys {
334	        if let Some(owner) = owners.get(&key) {
335	            let owner_key = pre_json_key(&owner.id);
336	            if owner_key != key {
337	                if let Some(version) = state.initial_versions.shift_remove(&key) {
338	                    state.initial_versions.entry(owner_key).or_insert(version);
339	                }
340	            }
341	        }
342	    }
343	    Ok(state)
344	}
