290	    let mut owners = BTreeMap::new();
291	    for key in &keys {
292	        if let Some(owner) = graph.packages().find(|p| pre_json_key(&p.id) == *key) {
293	            owners.insert(key.clone(), owner);
294	            continue;
295	        }
296	        let same: Vec<&callisto_model::Package> = graph
297	            .packages()
298	            .filter(|p| p.id.ecosystem().is_some() && p.id.name() == key.as_str())
299	            .collect();
