128	impl TagIndex {
129	    pub fn build<D: DependencyResolver>(
130	        git: &GitAccess<'_>,
131	        graph: &D,
132	        cfg: &ResolvedConfig,
133	    ) -> Result<Self, GraphError> {
134	        reject_shared_default_templates(graph)?;
135	        let mut last = BTreeMap::new();
136	        let mut templates = BTreeMap::new();
137	        let mut pre_cursor = BTreeMap::new();
138	        let diagnostics = Vec::new();
139	
140	        // Fetch the raw tag list exactly once for the whole build, not once
141	        // per package -- see `fetch_all_tags` for why.
142	        let all_tags = fetch_all_tags(git)?;
143	        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
144	        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();
145	
146	        for pkg in graph.packages() {
147	            // `TagTemplate::default_for` is the single source of truth for a
148	            // package's default tag template -- matches `release.rs`'s own
149	            // `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`.
150	            // Deliberately not `TagTemplate::parse(&format!("{name}@{{version}}"))`:
151	            // `parse` additionally validates git-ref-name legality, which
152	            // `default_for` does not, so the two could previously reject/accept a
153	            // package name differently. Using `default_for` here removes that
154	            // extra validation from this call site to align with the
155	            // already-shipped `release.rs` behavior.
156	            let tmpl = pkg
157	                .tag_template
158	                .clone()
159	                .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
160	            let grammar = pkg.version_grammar()?;
161	            let mut chosen = select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?.chosen;
162	            if chosen.is_none() {
163	                let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
164	                if let Some(previous) =
165	                    crate::config::resolve::resolve_package_config(&pkg.id, &package_ecosystems, cfg)?
166	                        .map(|package_config| package_config.previous_tag_templates.as_slice())
167	                {
168	                    for template in previous {
169	                        chosen = select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?.chosen;
170	                        if chosen.is_some() {
171	                            break;
172	                        }
173	                    }
174	                }
175	            }
176	            if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
177	                // A promoted package keeps the `{name}@` tags it made while its name was unique.
178	                let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
179	                let same: Vec<&callisto_model::Package> = graph
180	                    .packages()
181	                    .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
182	                    .collect();
183	                let mut owned = Vec::new();
184	                for tag in matching_tags(&all_tags, &unqualified)? {
185	                    if crate::sole_owner_at(git, tag, &same)?.is_some_and(|owner| owner.id == pkg.id) {
186	                        owned.push(tag);
187	                    }
188	                }
189	                chosen = select_last_tag(&unqualified, grammar, owned)
190	                    .map_err(GraphError::from)?
191	                    .chosen;
192	            }
193	            last.insert(pkg.id.clone(), chosen);
194	            templates.insert(pkg.id.clone(), tmpl);
195	            pre_cursor.insert(pkg.id.clone(), None);
196	        }
197	
198	        Ok(TagIndex {
199	            last,
200	            templates,
201	            pre_cursor,
202	            all_tags: all_tags_set,
203	            diagnostics,
204	        })
205	    }
