   512	    /// tags like `"v1.2.3"`, and a package with `tag_template: None` must
   513	    /// still fall back to the default `{name}@{version}` pattern.
   514	    #[test]
   515	    fn tag_index_uses_custom_tag_template_when_set() {
   516	        let dir = non_repo_dir();
   517	        let runner = FakeGitTagRunner::new(vec!["v1.2.3".to_string(), "pkg-default@4.5.6".to_string()]);
   518	
   519	        let manifest = ManifestDecl::new("Cargo.toml", ManifestRole::Canonical, ManifestFormat::CargoToml).unwrap();
   520	
   521	        let custom_pkg = Package {
   522	            id: PackageId::parse("custom-pkg").unwrap(),
   523	            manifests: vec![manifest.clone()],
   524	            changelog: None,
   525	            release_trigger: callisto_model::ReleaseTrigger::Changeset,
   526	            publish_to: Vec::new(),
   527	            tag_template: Some(TagTemplate::parse("v{version}").unwrap()),
   528	        };
   529	        let default_pkg = Package {
   530	            id: PackageId::parse("pkg-default").unwrap(),
   531	            manifests: vec![manifest],
   532	            changelog: None,
   533	            release_trigger: callisto_model::ReleaseTrigger::Changeset,
   534	            publish_to: Vec::new(),
   535	            tag_template: None,
   536	        };
   537	
   538	        let graph = FixedGraph {
   539	            pkgs: vec![custom_pkg, default_pkg],
   540	        };
   541	        let cfg = crate::config::load(dir.path()).unwrap();
   542	        let git = GitAccess::new(dir.path(), &runner);
   543	
   544	        let tags = TagIndex::build(&git, &graph, &cfg).expect("TagIndex::build must succeed");
   545	
   546	        let custom_id = PackageId::parse("custom-pkg").unwrap();
   547	        let default_id = PackageId::parse("pkg-default").unwrap();
   548	
   549	        assert_eq!(
   550	            tags.last_tag(&custom_id).map(|t| t.version.render().to_string()),
   551	            Some("1.2.3".to_string()),
   552	            "package with custom tag_template 'v{{version}}' must resolve 'v1.2.3'"
   553	        );
   554	        assert_eq!(
   555	            tags.last_tag(&default_id).map(|t| t.version.render().to_string()),
   556	            Some("4.5.6".to_string()),
   557	            "package with no tag_template must fall back to 'pkg-default@{{version}}'"
   558	        );
   559	    }
   560	
   561	    /// Spec: for a package with no explicit `tag_template`, `TagIndex::build`
   562	    /// must resolve the same default template `TagTemplate::default_for`
   563	    /// would produce -- `release.rs`'s existing tag-name construction already
   564	    /// calls `default_for` directly via
   565	    /// `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`,
   566	    /// and `TagIndex::build`'s own default must agree with it byte-for-byte
   567	    /// rather than re-deriving the same value through a separate
   568	    /// `TagTemplate::parse(&format!(...))` call that could diverge (e.g. by
   569	    /// additionally rejecting a package name `default_for` would silently
   570	    /// accept).
   571	    #[test]
   572	    fn tag_index_default_template_matches_tag_template_default_for() {
   573	        let dir = non_repo_dir();
   574	        let runner = FakeGitTagRunner::new(vec![]);
   575	        let graph = FixedGraph {
   576	            pkgs: vec![make_pkg("pkg-a")],
   577	        };
   578	        let cfg = crate::config::load(dir.path()).unwrap();
   579	        let git = GitAccess::new(dir.path(), &runner);
   580	
   581	        let tags = TagIndex::build(&git, &graph, &cfg).expect("TagIndex::build must succeed");
   582	
   583	        let pkg_id = PackageId::parse("pkg-a").unwrap();
   584	        assert_eq!(
   585	            tags.template(&pkg_id),
   586	            &TagTemplate::default_for(&pkg_id),
   587	            "TagIndex::build's default template must match TagTemplate::default_for exactly"
   588	        );
   589	    }
   590	
   591	    // A `glob_compile_count()`-based regression test for this behavior lives
   592	    // in `tests/tag_glob_cache_count_test.rs`, not here: `GLOB_COMPILE_COUNT`
   593	    // is a process-global counter, and this module's `--lib` test binary
   594	    // runs many other, non-`#[serial]` `TagIndex::build`/`matching_tags`
   595	    // tests concurrently that would race an exact-count assertion (same
   596	    // hazard `OPEN_CALL_COUNT`/`PERSIST_CALL_COUNT` are isolated from --
   597	    // see `tests/apply_persist_open_count_test.rs`).
   598	
   599	    /// Spec: when the `CommandRunner` returns `Err`, `TagIndex::build` must
   600	    /// propagate that error up
   601	    /// through the whole build rather than panicking or silently swallowing
   602	    /// it into an empty tag list per-package.
   603	    #[test]
   604	    fn test_tag_index_build_propagates_command_runner_error() {
   605	        let dir = non_repo_dir();
   606	        let runner = FailingRunner;
   607	        let graph = FixedGraph {
   608	            pkgs: vec![make_pkg("pkg-a")],
   609	        };
   610	        let cfg = crate::config::load(dir.path()).unwrap();
   611	        let git = GitAccess::new(dir.path(), &runner);
   612	
   613	        let is_command_err = matches!(
   614	            TagIndex::build(&git, &graph, &cfg),
   615	            Err(GraphError::Vcs(callisto_model::vcs::VcsError::Command(_)))
   616	        );
   617	
   618	        assert!(
   619	            is_command_err,
   620	            "TagIndex::build must propagate the CommandRunner error as GraphError::Command"
"}}}

