  7	use release_harness::{callisto, git, DECISION_PATH};
  8	
  9	/// Cargo `foo` 1.0.0 in `crates/foo`, released as `foo@1.0.0`.
 10	fn released_cargo_foo() -> tempfile::TempDir {
 11	    let dir = tempfile::tempdir().unwrap();
 12	    let root = dir.path();
 13	    callisto_fixtures::git::init_repo(root);
 14	    git(root, &["remote", "add", "origin", "https://github.com/example/foo.git"]);
 15	    fs::write(
 16	        root.join("Cargo.toml"),
 17	        "[workspace]\nmembers = [\"crates/foo\"]\nresolver = \"2\"\n",
 18	    )
 19	    .unwrap();
 20	    fs::create_dir_all(root.join("crates/foo/src")).unwrap();
 21	    fs::write(
 22	        root.join("crates/foo/Cargo.toml"),
 23	        "[package]\nname = \"foo\"\nversion = \"1.0.0\"\nedition = \"2021\"\n",
 24	    )
 25	    .unwrap();
 26	    fs::write(root.join("crates/foo/src/lib.rs"), "\n").unwrap();
 27	    fs::write(
 28	        root.join("crates/foo/CHANGELOG.md"),
 29	        "# foo\n\n## 1.0.0\n\n- First release.\n",
 30	    )
 31	    .unwrap();
 32	    callisto_fixtures::scaffold_callisto(root);
 33	    commit(root, "release foo 1.0.0");
 34	    git(root, &["tag", "foo@1.0.0"]);
 35	    dir
 36	}
 37	
 38	/// npm `foo` in `packages/foo`, with no tag configuration.
 39	fn add_npm_foo(root: &Path) {
 40	    fs::create_dir_all(root.join("packages/foo")).unwrap();
 41	    fs::write(
 42	        root.join("packages/foo/package.json"),
 43	        "{\n  \"name\": \"foo\",\n  \"version\": \"3.0.0\"\n}\n",
 44	    )
 45	    .unwrap();
 46	    commit(root, "add npm foo");
 47	}
 48	
 49	fn add_changeset(root: &Path, name: &str, selector: &str, bump: &str) {
 50	    fs::write(
 51	        root.join(format!(".changeset/{name}.md")),
 52	        format!("---\n\"{selector}\": {bump}\n---\n\nChange {name}.\n"),
 53	    )
 54	    .unwrap();
 55	    commit(root, &format!("changeset {name}"));
 56	}
 57	
 58	fn commit(root: &Path, message: &str) {
 59	    git(root, &["add", "-A"]);
 60	    git(root, &["commit", "-m", message]);
 61	}
 62	
 63	fn run_ok(root: &Path, args: &[&str]) -> serde_json::Value {
 64	    let out = callisto(root, args);
 65	    assert!(
 66	        out.status.success(),
 67	        "callisto {args:?} failed: {}",
 68	        String::from_utf8_lossy(&out.stderr)
 69	    );
 70	    serde_json::from_slice(&out.stdout).unwrap_or(serde_json::Value::Null)
 71	}
 72	
 73	fn cargo_foo_version(root: &Path) -> String {
 74	    let manifest = fs::read_to_string(root.join("crates/foo/Cargo.toml")).unwrap();
 75	    manifest
 76	        .lines()
 77	        .find_map(|line| line.strip_prefix("version = \""))
 78	        .and_then(|rest| rest.strip_suffix('"'))
 79	        .unwrap()
 80	        .to_string()
 81	}
 82	
 83	fn status_package<'a>(status: &'a serde_json::Value, id: &str) -> Option<&'a serde_json::Value> {
 84	    status["packages"].as_array()?.iter().find(|pkg| pkg["package"] == id)
 85	}
