 87	fn promoted_dual_npm_source_workspace() -> tempfile::TempDir {
 88	    let dir = tempfile::tempdir().unwrap();
 89	    let root = dir.path();
 90	    callisto_fixtures::git::init_repo(root);
 91	    fs::write(
 92	        root.join("Cargo.toml"),
 93	        "[workspace]\nmembers = [\"crates/source\", \"packages/app\"]\nresolver = \"2\"\n",
 94	    )
 95	    .unwrap();
 96	    fs::create_dir_all(root.join("crates/source/src")).unwrap();
