100	    )
101	    .unwrap();
102	    fs::write(root.join("crates/source/src/lib.rs"), "\n").unwrap();
103	    add_cargo_package(root, "packages/app", "app", "");
104	    fs::write(
105	        root.join("crates/source/package.json"),
106	        "{\n  \"name\": \"@native/source\",\n  \"version\": \"1.0.0\"\n}\n",
107	    )
108	    .unwrap();
109	    fs::create_dir_all(root.join("packages/source")).unwrap();
110	    fs::write(
111	        root.join("packages/source/package.json"),
112	        "{\n  \"name\": \"source\",\n  \"version\": \"1.0.0\"\n}\n",
113	    )
114	    .unwrap();
115	    fs::create_dir_all(root.join("packages/app/src")).unwrap();
116	    fs::write(root.join("packages/app/src/lib.rs"), "\n").unwrap();
117	    fs::write(
118	        root.join("packages/app/package.json"),
119	        "{\n  \"name\": \"@native/app\",\n  \"version\": \"1.0.0\",\n  \"dependencies\": {\"@native/source\": \"^1.0.0\"},\n  \"optionalDependencies\": {\"@native/source\": \"^1.0.0\"},\n  \"peerDependencies\": {\"@native/source\": \"^1.0.0\"},\n  \"devDependencies\": {\"@native/source\": \"^1.0.0\"}\n}\n",
120	    )
121	    .unwrap();
122	    fs::create_dir_all(root.join("packages/app-sibling")).unwrap();
123	    fs::write(
124	        root.join("packages/app-sibling/package.json"),
125	        "{\n  \"name\": \"app\",\n  \"version\": \"1.0.0\"\n}\n",
126	    )
127	    .unwrap();
128	    callisto_fixtures::scaffold_callisto(root);
129	    commit(root, "initial promoted dual npm source");
130	    dir
131	}
