133	fn cargo_workspace(root: &Path, members: &[&str]) {
134	    callisto_fixtures::git::init_repo(root);
135	    let member_list = members
136	        .iter()
137	        .map(|member| format!("\"{member}\""))
138	        .collect::<Vec<_>>()
139	        .join(", ");
140	    fs::write(
141	        root.join("Cargo.toml"),
142	        format!("[workspace]\nmembers = [{member_list}]\nresolver = \"2\"\n"),
143	    )
144	    .unwrap();
145	    callisto_fixtures::scaffold_callisto(root);
146	}
147	
148	fn add_cargo_package(root: &Path, relative: &str, name: &str, extra: &str) {
149	    fs::create_dir_all(root.join(relative).join("src")).unwrap();
150	    fs::write(
151	        root.join(relative).join("Cargo.toml"),
152	        format!("[package]\nname = \"{name}\"\nversion = \"1.0.0\"\nedition = \"2021\"\n{extra}"),
153	    )
154	    .unwrap();
155	    fs::write(root.join(relative).join("src/lib.rs"), "\n").unwrap();
156	}
