158	#[test]
159	fn promotion_keeps_the_last_tag_and_the_changelog() {
160	    let dir = released_cargo_foo();
161	    let root = dir.path();
162	    add_changeset(root, "feature", "cargo/foo", "minor");
163	    add_npm_foo(root);
164	
165	    let status = run_ok(root, &["status"]);
166	    let foo = status_package(&status, "cargo/foo").unwrap_or_else(|| panic!("no cargo/foo in status: {status}"));
167	    assert_eq!(foo["lastReleasedVersion"], "1.0.0", "status: {status}");
168	
169	    run_ok(root, &["version", "--no-refresh-lockfiles"]);
170	    assert_eq!(cargo_foo_version(root), "1.1.0");
171	    let changelog = fs::read_to_string(root.join("crates/foo/CHANGELOG.md")).unwrap();
172	    assert!(
173	        changelog.contains("1.1.0") && changelog.contains("## 1.0.0"),
174	        "{changelog}"
175	    );
176	    assert!(!root.join("packages/foo/CHANGELOG.md").exists());
177	}
