179	#[test]
180	fn same_named_packages_need_no_tag_configuration() {
181	    let dir = released_cargo_foo();
182	    let root = dir.path();
183	    add_npm_foo(root);
184	    add_changeset(root, "feature", "cargo/foo", "minor");
185	
186	    let status = run_ok(root, &["status"]);
187	    let npm = status_package(&status, "npm/foo").unwrap_or_else(|| panic!("no npm/foo in status: {status}"));
188	    assert!(
189	        npm["lastReleasedVersion"].is_null(),
190	        "npm/foo must not claim cargo foo's tags: {status}"
191	    );
192	
193	    run_ok(root, &["version", "--no-refresh-lockfiles"]);
194	    assert_eq!(cargo_foo_version(root), "1.1.0");
195	}
