197	#[test]
198	fn a_bare_changeset_name_after_promotion_says_how_to_qualify_it() {
199	    let dir = released_cargo_foo();
200	    let root = dir.path();
201	    add_npm_foo(root);
202	    add_changeset(root, "feature", "foo", "minor");
203	
