231	#[test]
232	fn a_decision_written_by_version_verifies_in_release_plan_after_promotion() {
233	    let dir = released_cargo_foo();
234	    let root = dir.path();
235	    add_npm_foo(root);
236	    add_changeset(root, "feature", "cargo/foo", "minor");
237	    run_ok(
