239	        &["version", "--no-refresh-lockfiles", "--emit-decision", DECISION_PATH],
240	    );
241	    commit(root, "release");
242	    let release_commit = git(root, &["rev-parse", "HEAD"]);
243	    git(root, &["checkout", "--detach", &release_commit]);
244	    let external = tempfile::tempdir().unwrap();
245	    let out = external.path().join("intent.json");
246	    run_ok(
247	        root,
248	        &[
249	            "release",
250	            "plan",
251	            "--from-release-commit",
252	            &release_commit,
253	            "--decision",
254	            DECISION_PATH,
255	            "--orchestration-revision",
256	            &release_commit,
