261	        ],
262	    );
263	    let intent: serde_json::Value = serde_json::from_slice(&fs::read(&out).unwrap()).unwrap();
264	    let tagged = intent["operations"].as_array().unwrap().iter().any(|op| {
265	        op["id"]["package"] == "cargo/foo" && op["id"]["version"] == "1.1.0" && op["id"]["role"]["kind"] == "tag"
266	    });
267	    assert!(tagged, "{intent}");
268	}
