270	#[test]
271	fn display_id_is_bare_when_unique_and_qualified_when_promoted() {
272	    let dir = released_cargo_foo();
273	    let root = dir.path();
274	
275	    let status = run_ok(root, &["status"]);
276	    assert!(status_package(&status, "foo").is_some(), "status: {status}");
277	    run_ok(root, &["add", "--package", "cargo/foo:patch", "--summary", "Before"]);
278	
279	    add_npm_foo(root);
280	    let status = run_ok(root, &["status"]);
281	    assert!(status_package(&status, "cargo/foo").is_some(), "status: {status}");
282	    assert!(status_package(&status, "npm/foo").is_some(), "status: {status}");
283	    assert!(status_package(&status, "foo").is_none(), "status: {status}");
284	    run_ok(root, &["add", "--package", "cargo/foo:patch", "--summary", "After"]);
285	
286	    let out = callisto(root, &["add", "--package", "foo:patch", "--summary", "Ambiguous"]);
287	    let stderr = String::from_utf8_lossy(&out.stderr);
288	    assert!(stderr.contains("E103") && stderr.contains("cargo/foo"), "{stderr}");
289	}
